const byModel = new Map<string, Ssm4CgdwFingerprint[]>();
const byFp = new Map<string, Ssm4CgdwFingerprint[]>();
for (const p of SSM4_CGDW_FINGERPRINTS) {
  const list = byModel.get(p.appliedModel);
  if (list) list.push(p);
  else byModel.set(p.appliedModel, [p]);
  const fl = byFp.get(p.fp);
  if (fl) fl.push(p);
  else byFp.set(p.fp, [p]);
}

export function fingerprintFromMeterDids(didHexById: Record<string, string>): string {
  return SSM4_CGDW_FP_DID_KEYS.map((k) => {
    const raw = (didHexById[k] ?? didHexById[k.toLowerCase()] ?? "").trim().toUpperCase();
    if (!raw) return "__"; // not read from ECU
    if (raw === "--" || raw === "ABSENT") return "--";
    const tok = (raw.split(/\s+/)[0] ?? "").slice(0, 2);
    return tok.length === 2 ? tok : "__";
  }).join("");
}

function packMeterMatch(
  hits: readonly Ssm4CgdwFingerprint[],
  fp: string,
): { optionCode: string; appliedModel: string | null; unique: boolean; candidates: string[]; fp: string } | null {
  if (!hits.length) return null;
  const opts = [...new Set(hits.map((p) => p.optionCode))];
  const apps = [...new Set(hits.map((p) => p.appliedModel))];
  return {
    optionCode: opts[0]!,
    appliedModel: apps.length === 1 ? apps[0]! : null,
    unique: opts.length === 1 && apps.length === 1,
    candidates: [...new Set(hits.map((p) => `${p.appliedModel}+${p.optionCode}`))],
    fp,
  };
}

/** Compare meter dump to catalog fp: __ = unread (skip), -- = absent in row. */
function fingerprintCompatible(gotFp: string, wantFp: string): boolean {
  if (gotFp.length !== wantFp.length) return false;
  for (let i = 0; i < gotFp.length; i += 2) {
    const got = gotFp.slice(i, i + 2);
    const want = wantFp.slice(i, i + 2);
    if (got === "__") continue;
    if (got !== want) return false;
  }
  return SSM4_CGDW_FP_DID_KEYS.some((_, i) => gotFp.slice(i * 2, i * 2 + 2) !== "__");
}

function compatibleHits(list: readonly Ssm4CgdwFingerprint[], fp: string): Ssm4CgdwFingerprint[] {
  return list.filter((p) => fingerprintCompatible(fp, p.fp));
}

export function matchSsm4OptionFromMeterDids(
  appliedModel: string | null | undefined,
  didHexById: Record<string, string>,
): { optionCode: string; appliedModel: string | null; unique: boolean; candidates: string[]; fp: string } | null {
  const fp = fingerprintFromMeterDids(didHexById);
  if (!/[0-9A-F]/.test(fp.replace(/[_-]/g, ""))) return null;
  const knownSlots = SSM4_CGDW_FP_DID_KEYS.filter((_, i) => fp.slice(i * 2, i * 2 + 2) !== "__").length;
  const app = appliedModel?.trim().toUpperCase() || "";
  if (app) {
    const list = byModel.get(app) ?? [];
    const exact = list.filter((p) => p.fp === fp);
    return packMeterMatch(exact.length ? exact : compatibleHits(list, fp), fp);
  }
  // Global: prefer exact full fingerprint; else compatible with enough known slots.
  const exact = byFp.get(fp) ?? [];
  if (exact.length) return packMeterMatch(exact, fp);
  if (knownSlots < 8) return null; // too few DIDs → do not guess Applied globally
  return packMeterMatch(compatibleHits(SSM4_CGDW_FINGERPRINTS, fp), fp);
}
